import { useMemo, useState } from "react";
import { Button, Card, FieldFrame, PageHeader, RecordList, Select, Tag, Typography } from "@autograph/components";
import { KpiStripComposition, RecordDetailPanel, RecordListDetailLayout } from "@autograph/compositions";
type Severity="critical"|"warning";type Product={id:string;sku:string;name:string;location:string;locationLabel:string;severity:Severity;onHand:number;reserved:number;reorderPoint:number;daysCover:number;supplier:string;leadTime:string;pack:number;minCases:number;lastReceipt:string;contact:string;terms:string};
const products:Product[]=[{id:"atlas",sku:"HW-1048",name:"Atlas nitrile gloves — Size M",location:"oakland",locationLabel:"Oakland DC",severity:"critical",onHand:18,reserved:12,reorderPoint:72,daysCover:1.4,supplier:"Northstar Medical Supply",leadTime:"4 business days",pack:24,minCases:4,lastReceipt:"96 units on 14 Aug",contact:"orders@northstarmed.example",terms:"Net 30 · minimum 4 cases"},{id:"beacon",sku:"CL-2201",name:"Beacon surface disinfectant",location:"oakland",locationLabel:"Oakland DC",severity:"warning",onHand:34,reserved:6,reorderPoint:60,daysCover:3.8,supplier:"Clearwell Distribution",leadTime:"6 business days",pack:12,minCases:0,lastReceipt:"60 units on 11 Aug",contact:"supply@clearwell.example",terms:"Net 30 · no minimum"},{id:"cedar",sku:"PK-0912",name:"Cedar specimen bags",location:"reno",locationLabel:"Reno Clinic",severity:"critical",onHand:9,reserved:3,reorderPoint:48,daysCover:1.1,supplier:"Northstar Medical Supply",leadTime:"3 business days",pack:50,minCases:2,lastReceipt:"100 units on 2 Aug",contact:"orders@northstarmed.example",terms:"Net 30 · minimum 2 cases"},{id:"delta",sku:"PP-3140",name:"Delta isolation gowns",location:"reno",locationLabel:"Reno Clinic",severity:"warning",onHand:27,reserved:5,reorderPoint:45,daysCover:4.2,supplier:"Westline Clinical",leadTime:"8 business days",pack:20,minCases:3,lastReceipt:"80 units on 8 Aug",contact:"service@westline.example",terms:"Net 45 · minimum 3 cases"}];
export default function StockExceptions(){const[location,setLocation]=useState("all");const[severity,setSeverity]=useState("all");const[selectedId,setSelectedId]=useState("atlas");const[hasEstablishedSelection,setHasEstablishedSelection]=useState(false);const[stage,setStage]=useState<"ready"|"confirm"|"done">("ready");const filtered=useMemo(()=>products.filter(p=>(location==="all"||p.location===location)&&(severity==="all"||p.severity===severity)).sort((a,b)=>(a.severity===b.severity?0:a.severity==="critical"?-1:1)||(a.daysCover-b.daysCover)||a.id.localeCompare(b.id)),[location,severity]);const selected=filtered.find(p=>p.id===selectedId);const changeFilters=(nextLocation:string,nextSeverity:string)=>{const next=products.filter(p=>(nextLocation==="all"||p.location===nextLocation)&&(nextSeverity==="all"||p.severity===nextSeverity));setSelectedId(current=>next.some(p=>p.id===current)?current:(next[0]?.id??""));setHasEstablishedSelection(false);setStage("ready")};const resetFilters=()=>{setLocation("all");setSeverity("all");setSelectedId("atlas");setHasEstablishedSelection(false);setStage("ready")};const shortfall=selected?Math.max(0,selected.reorderPoint-selected.onHand):0;const roundedCases=selected&&shortfall>0?Math.ceil(shortfall/selected.pack):0;const caseCount=selected&&shortfall>0?Math.max(roundedCases,selected.minCases):0;const quantity=selected?caseCount*selected.pack:0;const projected=selected?selected.onHand+quantity:0;
const filters=<section aria-label="Exception filters" className="grid grid-cols-1 gap-[var(--space-3)] rounded-[var(--radius-panel)] border border-[var(--color-border-subtle)] bg-[var(--color-bg-surface)] p-[var(--space-3)] sm:grid-cols-2"><FieldFrame label="Location" className="min-w-0 w-full"><Select size="sm" value={location} options={[{value:"all",label:"All locations"},{value:"oakland",label:"Oakland DC"},{value:"reno",label:"Reno Clinic"},{value:"none",label:"Portland Hub (0)"}]} onValueChange={v=>{setLocation(v);changeFilters(v,severity)}}/></FieldFrame><FieldFrame label="Severity" className="min-w-0 w-full"><Select size="sm" value={severity} options={[{value:"all",label:"All severities"},{value:"critical",label:"Critical"},{value:"warning",label:"Low"}]} onValueChange={v=>{setSeverity(v);changeFilters(location,v)}}/></FieldFrame></section>;
const replenishmentExplanation=selected?selected.minCases>roundedCases?`${shortfall}-unit gap rounds to ${roundedCases} cases. The supplier minimum is larger than the rounded gap, so it takes precedence: ${caseCount} × ${selected.pack} = ${quantity} units.`:`${shortfall}-unit gap rounds to ${caseCount} × ${selected.pack} = ${quantity} units.`:"";
const resultItems=selected?[{type:"note" as const,id:"decision-quantities",body:`Current on-hand ${selected.onHand} units; modeled addition ${quantity} units; projected on-hand ${projected} units.`},{type:"field" as const,id:"no-order",label:"Simulation only",value:stage==="confirm"?"No order will be placed and underlying stock will remain unchanged.":"No order was placed and underlying stock is unchanged.",layout:"stacked" as const},{type:"field" as const,id:"assumption",label:"Model assumption",value:`Uses gross on-hand; ${selected.reserved} reserved units are shown separately against the ${selected.reorderPoint}-unit reorder point.`,layout:"stacked" as const},{type:"field" as const,id:"replenishment",label:"Replenishment",value:replenishmentExplanation,layout:"stacked" as const}]:[];
const stockSection=selected?{id:"stock",title:`Stock evidence · ${shortfall} units below reorder point`,collapsible:stage==="done",defaultOpen:stage!=="done",items:[{type:"field" as const,id:"onHand",label:"Gross on-hand",value:`${selected.onHand} units`},{type:"field" as const,id:"reserved",label:"Reserved",value:`${selected.reserved} units`},{type:"field" as const,id:"reorder",label:"Reorder point",value:`${selected.reorderPoint} units`},{type:"field" as const,id:"cover",label:"Days of cover",value:`${selected.daysCover} days`},{type:"field" as const,id:"supplier",label:"Supplier",value:selected.supplier},{type:"field" as const,id:"lead",label:"Lead time",value:selected.leadTime}]}:null;const supplierSection=selected?{id:"supplier-secondary",title:"Secondary supplier facts",defaultOpen:false,items:[{type:"field" as const,id:"supplier-pack",label:"Case pack",value:`${selected.pack} units`},{type:"field" as const,id:"receipt",label:"Last receipt",value:selected.lastReceipt},{type:"field" as const,id:"contact",label:"Order contact",value:selected.contact},{type:"field" as const,id:"terms",label:"Terms",value:selected.terms}]}:null;
const summaryText=location==="all"&&severity==="all"?`${products.length} exceptions`:`${filtered.length} matching · ${products.length} total`;const recordList=<RecordList ariaLabel="Low-stock products" heading="Exceptions" summary={<><Typography as="span" variant="body" className="block">{summaryText}</Typography><Typography as="span" variant="body" tone="primary" className="block">Critical first · lowest cover</Typography></>} selectedId={selectedId} onSelect={id=>{setSelectedId(id);setHasEstablishedSelection(true);setStage("ready")}} items={filtered.map(p=>({id:p.id,primary:p.name,secondary:<><Typography as="span" variant="body" className="block">{p.sku} · {p.locationLabel}</Typography><Typography as="span" variant="body" className="block">{Math.max(0,p.reorderPoint-p.onHand)} units below reorder point</Typography></>,trailing:<><Tag size="md" tone={p.severity==="critical"?"red":"amber"} label={p.severity==="critical"?"Critical":"Low"}/><Typography as="span" variant="body-strong">{p.daysCover} days cover</Typography></>}))}/>;const list=<div className="grid gap-[var(--space-3)]">{filters}{recordList}</div>;
const detail=selected?<div><RecordDetailPanel labelEmphasis="primary" title={selected.name} subtitle={<><Typography as="span" variant="body">{selected.sku} · {selected.locationLabel} · </Typography><Tag size="md" tone={selected.severity==="critical"?"red":"amber"} label={selected.severity==="critical"?"Critical":"Low"}/></>} sections={stage==="confirm"?[{id:"confirm",title:`Confirm ${quantity}-unit modeled replenishment`,collapsible:false,items:resultItems}]:stage==="done"?[{id:"mock-result",title:`Modeled replenishment: ${quantity} units · ${projected} projected on-hand`,collapsible:false,items:resultItems}]:[stockSection!,supplierSection!]} renderItem={item=>item.id==="decision-quantities"&&selected?<KpiStripComposition spec={{type:"kpi_strip",config:{layout:"container",labelEmphasis:"primary",items:[{id:"current",label:"Current on-hand",value:`${selected.onHand} units`},{id:"addition",label:"Modeled addition",value:`${quantity} units`},{id:"projected",label:"Projected on-hand",value:`${projected} units`}]}}}/>:undefined} actions={stage==="ready"?[{id:"try",label:"Try mock replenishment",intent:"primary-strong"}]:stage==="confirm"?[{id:"cancel",label:"Cancel"},{id:"confirm",label:"Confirm mock",intent:"primary-strong"}]:[{id:"reset",label:"Reset mock"}]} onAction={id=>{if(id==="try")setStage("confirm");if(id==="cancel"||id==="reset")setStage("ready");if(id==="confirm")setStage("done")}}/></div>:null;
return <main className="min-h-screen bg-[var(--color-bg-page)] px-[var(--space-6)] py-[var(--space-6)]"><div className="mx-auto w-full max-w-[1240px]"><PageHeader title="Stock exceptions" subtitle="Review low-stock evidence and model a replenishment without changing inventory."/><div className="mx-auto mt-[var(--space-5)] w-full max-w-[1240px]">{filtered.length===0?<div className="grid gap-[var(--space-3)]">{filters}<Card><div className="px-[var(--space-6)] py-[var(--space-8)]"><Typography variant="section-title">No exceptions match these filters</Typography><Typography variant="body" tone="muted" className="mt-[var(--space-2)]">Change location or severity, or reset both filters to return to the full exception list.</Typography><Button size="sm" className="mt-[var(--space-4)]" onClick={resetFilters}>Reset filters</Button></div></Card></div>:<RecordListDetailLayout list={list} detail={detail} hasSelection={Boolean(selected)} showDetailOnConstrained={hasEstablishedSelection} selectedId={selectedId||undefined} onBack={()=>{setHasEstablishedSelection(false);setSelectedId("")}} backLabel="Back to exceptions"/>}</div></div></main>}
